def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal divider: align the two equal-sized regions across it.
    for r in range(h):
        if len(set(grid[r])) == 1:
            n = min(r, h - r - 1)
            if n:
                return [
                    [2 if grid[i][c] != 0 and grid[r + 1 + i][c] != 0 else 0
                     for c in range(w)]
                    for i in range(n)
                ]

    # Vertical divider.
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            n = min(c, w - c - 1)
            return [
                [2 if grid[r][c - n + i] != 0 and grid[r][c + 1 + i] != 0 else 0
                 for i in range(n)]
                for r in range(h)
            ]
